<script setup lang="ts">import {reactive} from 'vue'; const props=defineProps<{source?:Record<string,unknown>|null}>(); const emit=defineEmits<{save:[value:Record<string,unknown>];cancel:[]}>(); const form=reactive({name:String(props.source?.name||''),ownerName:String(props.source?.ownerName||''),amount:'',expectedCloseDate:'',relatedProduct:''});</script>
<template><form class="work-item-form" @submit.prevent="emit('save',{...form})"><label>商机名称<input v-model="form.name" required placeholder="请输入商机名称"/></label><label>负责人<input v-model="form.ownerName" required placeholder="请输入负责人"/></label><div class="form-grid"><label>预计金额<input v-model="form.amount" type="number" placeholder="请输入预计金额"/></label><label>预计成交日期<input v-model="form.expectedCloseDate" type="date"/></label></div><label>关联产品<input v-model="form.relatedProduct" placeholder="请输入关联产品"/></label><div class="form-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button class="primary">确认转化</button></div></form></template>
